import React from "react";

function AssignmentResult({ vehicles }) {
  if (!vehicles.length) return null;

  return (
    <div className="results-box">
      <h2>Assignment Results</h2>
      {vehicles.map((veh, vi) => (
        <div key={vi} className="vehicle-result">
          <h3>
            Vehicle: {veh.truckId || "—"} — Type: {veh.type || "—"} · Capacity: {veh.capacity || 0}kg
          </h3>
          <p><strong>Current Load:</strong> {veh.currentLoad || 0}kg</p>
          <div>
            <strong>Assigned Customers:</strong>
            <ul>
              {veh.assignedCustomers.map((c, ci) => (
                <li key={ci}>
                  {c.CustomerID} ({c.customerName}) – {c.loadWeight}kg
                </li>
              ))}
            </ul>
          </div>
          <div>
            <strong>Route:</strong>
            <ol>
              {veh.route.map((step, si) => (
                <li key={si}>
                  {step[0] === "start" && `Start at (${step[1]}, ${step[2]})`}
                  {step[0] === "storage" && `Pick up at Storage ${step[1]} (${step[2]}, ${step[3]})`}
                  {step[0] === "customer" && `Deliver to Customer ${step[1]} (${step[2]}, ${step[3]})`}
                </li>
              ))}
            </ol>
          </div>
        </div>
      ))}
    </div>
  );
}

export default AssignmentResult;
